package cli

import (
	"bytes"
	"strings"
	"testing"
)

// dispatchCommands mirrors the real command tokens handled by Run's switch in
// root.go. `help` and `version` are included — they are commands with their own
// doc entries; only the flag aliases (--help, -h, --version, -v) are left out,
// since they carry no command word. If you add a command to the switch, add it
// here and give it a commandDoc.
var dispatchCommands = []string{
	"diff", "commit", "checkpoint", "analyze", "doctor", "capabilities",
	"snapshot", "snapshot-query", "symbols", "edges", "query", "search", "context", "store", "index", "health", "def",
	"explain", "neighbors", "impact", "risk", "verify", "stats", "agent-guide",
	"setup", "hook", "version", "help",
}

// TestUnknownFlagNamesTheVersion pins that a flag-shaped argument this binary does not know reads
// as version skew rather than as a broken tool.
//
// This is the third way a benchmark cell can silently stop calling the graph: a harness whose flag
// set was built for a newer binary gets exit 1 and an empty payload on EVERY call, the agent's
// first mandated action fails, and the whole run measures a graph arm that never reached the graph.
// The message is the only place that failure can be diagnosed from a transcript.
func TestUnknownFlagNamesTheVersion(t *testing.T) {
	t.Parallel()
	repo := t.TempDir()
	write(t, repo, "alpha.py", "def alpha_widget():\n    return True\n")

	err := Run(t.Context(), Options{Version: "0.9.9", Env: EntireEnv{RepoRoot: repo}, Stdout: &bytes.Buffer{}},
		[]string{"search", "--repo", repo, "--query", "alpha", "--flag-from-a-newer-build"})
	if err == nil {
		t.Fatal("an unknown flag was accepted")
	}
	for _, want := range []string{"0.9.9", "--flag-from-a-newer-build", "--help", "older"} {
		if !strings.Contains(err.Error(), want) {
			t.Fatalf("error does not mention %q: %v", want, err)
		}
	}

	// A positional argument is a typo, not a stale deploy, and keeps the plain wording — otherwise
	// every mistyped command would start advertising version numbers.
	err = Run(t.Context(), Options{Version: "0.9.9", Env: EntireEnv{RepoRoot: repo}, Stdout: &bytes.Buffer{}},
		[]string{"search", "--repo", repo, "--query", "alpha", "stray"})
	if err == nil {
		t.Fatal("a stray positional argument was accepted")
	}
	if !strings.Contains(err.Error(), "unexpected arguments") || strings.Contains(err.Error(), "0.9.9") {
		t.Fatalf("positional argument did not keep the plain wording: %v", err)
	}
}

// TestRegistryMatchesDispatch enforces that the help registry and the dispatch
// switch cover exactly the same set of commands, so help never drifts from what
// the CLI actually accepts.
func TestRegistryMatchesDispatch(t *testing.T) {
	docNames := map[string]bool{}
	for _, d := range commandDocs {
		if docNames[d.name] {
			t.Fatalf("duplicate commandDoc for %q", d.name)
		}
		docNames[d.name] = true
	}

	dispatch := map[string]bool{}
	for _, c := range dispatchCommands {
		dispatch[c] = true
	}

	for _, c := range dispatchCommands {
		if !docNames[c] {
			t.Errorf("dispatched command %q has no commandDoc (missing help)", c)
		}
	}
	for name := range docNames {
		if !dispatch[name] {
			t.Errorf("commandDoc %q is not dispatched by Run (stale help)", name)
		}
	}
}

// TestEveryCommandDocResolvesToUsage makes sure each command (aliases resolved)
// renders a Usage block — i.e. no listed command has an empty doc.
func TestEveryCommandDocResolvesToUsage(t *testing.T) {
	for _, name := range commandNames() {
		var out bytes.Buffer
		renderCommandHelp(&out, name)
		if !strings.Contains(out.String(), "Usage:") {
			t.Errorf("%s --help produced no Usage block:\n%s", name, out.String())
		}
	}
}

func TestNewPublicCommandsRenderSpecificHelp(t *testing.T) {
	tests := []struct {
		name string
		want []string
	}{
		{
			name: "snapshot-query",
			want: []string{
				"Usage:\n  entire graph snapshot-query",
				"--input", "--symbol", "--from", "--relation", "--format",
			},
		},
		{
			name: "explain",
			want: []string{
				"Usage:\n  entire graph explain",
				"--repo", "--profile", "--format", "--max-symbols", "--max-context-bytes",
			},
		},
		{
			name: "snapshot",
			want: []string{"--format ndjson|compact-ndjson|scip"},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			var out bytes.Buffer
			renderCommandHelp(&out, tt.name)
			for _, want := range tt.want {
				if !strings.Contains(out.String(), want) {
					t.Errorf("%s --help missing %q:\n%s", tt.name, want, out.String())
				}
			}
		})
	}
}

// TestRootHelpGroupsAndCommands checks the grouped root listing shows every
// non-hidden command and the three group headers in order.
func TestRootHelpGroupsAndCommands(t *testing.T) {
	var out bytes.Buffer
	renderRootHelp(&out)
	root := out.String()

	last := -1
	for _, g := range groupOrder {
		title := groupTitles[g]
		idx := strings.Index(root, title+":")
		if idx < 0 {
			t.Fatalf("root help missing group header %q", title)
		}
		if idx < last {
			t.Fatalf("group header %q out of order", title)
		}
		last = idx
	}

	for _, name := range commandNames() {
		if !strings.Contains(root, "\n  "+name+" ") && !strings.Contains(root, "\n  "+name+"\n") {
			t.Errorf("root help omitted command %q", name)
		}
	}

	// The hidden `analyze` alias must not appear as its own listing row.
	if strings.Contains(root, "\n  analyze ") {
		t.Error("root help listed the hidden alias `analyze`")
	}
}

// TestRunRendersPerCommandHelp exercises the --help interception wired into Run.
func TestRunRendersPerCommandHelp(t *testing.T) {
	cases := []struct {
		args     []string
		contains []string
	}{
		{[]string{"search", "--help"}, []string{"Usage:", "Flags:", "--query"}},
		{[]string{"store", "--help"}, []string{"Usage:", "entire graph store", "--repo", "--profile", "--cache-dir", "--ignore-file", "--include-file"}},
		{[]string{"context", "--help"}, []string{"--ignore-file", "--include-file"}},
		{[]string{"neighbors", "-h"}, []string{"Flags:", "16384"}},
		{[]string{"analyze", "--help"}, []string{"entire graph diff"}}, // alias resolves
	}
	for _, tc := range cases {
		var stdout, stderr bytes.Buffer
		err := Run(t.Context(), Options{Stdout: &stdout, Stderr: &stderr}, tc.args)
		if err != nil {
			t.Fatalf("Run(%v) returned error: %v", tc.args, err)
		}
		for _, want := range tc.contains {
			if !strings.Contains(stdout.String(), want) {
				t.Errorf("Run(%v) help missing %q:\n%s", tc.args, want, stdout.String())
			}
		}
	}
}

// TestRunUnknownCommandHints keeps the unknown-command error pointing users at
// the help listing.
func TestRunUnknownCommandHints(t *testing.T) {
	var stdout, stderr bytes.Buffer
	err := Run(t.Context(), Options{Stdout: &stdout, Stderr: &stderr}, []string{"frobnicate"})
	if err == nil {
		t.Fatal("expected an error for an unknown command")
	}
	if !strings.Contains(err.Error(), "unknown command") || !strings.Contains(err.Error(), "entire graph help") {
		t.Errorf("unknown-command error lacks a help hint: %v", err)
	}
}

package cli

import (
	"fmt"
	"sort"
	"strings"
)

// The preflight: prove the binary accepts the command line before a run depends on it.
//
// Three ways a search verb can stop answering, all observed or reproducible, all silent:
//
//   - a pre-delivered payload file that exists but is EMPTY — stdout got zero bytes and the process
//     exited 0, so the exit code, the harness and the transcript all recorded a healthy call;
//   - a session state file reused across tasks — every task after the first replayed the first
//     one's payload, naming files that are not in the tree the agent is looking at;
//   - a flag set built for a newer binary — exit 1 and an empty payload on every call.
//
// The first two now fail loudly at the call. The third does too, but it fails on the FIRST AGENT
// TURN of every instance, which is the worst possible time to find out: by then the run is already
// under way, and what a reviewer sees afterwards is a graph arm whose numbers look like the
// baseline. The fix is to find out BEFORE the run, from one cheap call that parses the exact
// command line the run is about to use and refuses if this binary cannot serve it.
//
// It parses; it never executes. That is what makes it safe to run against a production command
// line — no repository is touched, no index is built, nothing is written.
//
// It runs each command's REAL parser rather than a list of known flag names, so it cannot drift
// from what the command actually accepts — that drift is the whole failure being guarded against.
// The consequence is that where a parser also enforces required flags (verify wants a baseline),
// the preflight enforces them too. Assert the command line you actually intend to run, not a
// fragment of it.

// preflightParsers maps a command word to a parse-only check: it returns an error when this binary
// would reject the given arguments. Commands whose parsers return trailing arguments report those
// through unexpectedArgumentsError, so the preflight's message is the same one the real call would
// have produced.
var preflightParsers = map[string]func(version string, args []string) error{
	"query": func(version string, args []string) error {
		_, rest, err := parseSearchFlags(args)
		if err != nil {
			return err
		}
		if len(rest) != 0 {
			return unexpectedArgumentsError("query", version, rest)
		}
		return nil
	},
	"index": func(version string, args []string) error {
		_, rest, err := parseIndexFlags(args)
		if err != nil {
			return err
		}
		if len(rest) != 0 {
			return unexpectedArgumentsError("index", version, rest)
		}
		return nil
	},
	"stats": func(version string, args []string) error {
		_, rest, err := parseStatsFlags(args)
		if err != nil {
			return err
		}
		if len(rest) != 0 {
			return unexpectedArgumentsError("stats", version, rest)
		}
		return nil
	},
	"def":       func(_ string, args []string) error { _, err := parseDefFlags(args); return err },
	"impact":    func(_ string, args []string) error { _, err := parseImpactFlags(args); return err },
	"neighbors": func(_ string, args []string) error { _, err := parseNeighborFlags(args); return err },
	"verify":    func(_ string, args []string) error { _, err := parseVerifyFlags(args); return err },
}

// preflightCommands is the sorted command list, for the error a caller gets when it names something
// this binary cannot check.
func preflightCommands() []string {
	names := make([]string, 0, len(preflightParsers))
	for name := range preflightParsers {
		names = append(names, name)
	}
	sort.Strings(names)
	return names
}

// splitPreflightCommandLine splits an --assert spec into argv. It honours single
// and double quotes so an argument may contain spaces, which strings.Fields could
// not express, but a backslash OUTSIDE quotes is an ordinary character: this is a
// command line, not a shell line, and an unquoted Windows path is a normal input.
// Escaping there rewrote C:\work\repo into C:workrepo, and an escaped space
// merged two arguments into one and returned no error, so the preflight approved
// a command line the caller never wrote. Inside double quotes a backslash still
// escapes ", \, $ and `, and anything else is kept verbatim so paths survive.
func splitPreflightCommandLine(spec string) ([]string, error) {
	var fields []string
	var field strings.Builder
	var quote byte
	started := false
	for index := 0; index < len(spec); index++ {
		character := spec[index]
		if quote == '\'' {
			if character == '\'' {
				quote = 0
			} else {
				field.WriteByte(character)
			}
			started = true
			continue
		}
		if quote == '"' {
			switch character {
			case '"':
				quote = 0
			case '\\':
				if index+1 >= len(spec) {
					return nil, fmt.Errorf("command line ends with an escape")
				}
				index++
				next := spec[index]
				if next == '"' || next == '\\' || next == '$' || next == '`' {
					field.WriteByte(next)
				} else {
					field.WriteByte('\\')
					field.WriteByte(next)
				}
			default:
				field.WriteByte(character)
			}
			started = true
			continue
		}
		switch character {
		case '\'', '"':
			quote = character
			started = true
		case ' ', '\t', '\r', '\n':
			if started {
				fields = append(fields, field.String())
				field.Reset()
				started = false
			}
		default:
			field.WriteByte(character)
			started = true
		}
	}
	if quote != 0 {
		return nil, fmt.Errorf("command line has an unterminated quote")
	}
	if started {
		fields = append(fields, field.String())
	}
	return fields, nil
}

// checkPreflight parses one `<command> [args...]` string and reports whether this binary accepts it.
func checkPreflight(version, spec string) error {
	fields, err := splitPreflightCommandLine(spec)
	if err != nil {
		return fmt.Errorf("--assert %q: %w", spec, err)
	}
	if len(fields) == 0 {
		return fmt.Errorf("--assert needs a command line, for example --assert %q", "query --profile full")
	}
	command, args := fields[0], fields[1:]
	if command == "search" {
		command = "query"
	}
	parse, ok := preflightParsers[command]
	if !ok {
		return fmt.Errorf("--assert cannot check %q: this binary can check %s",
			command, strings.Join(preflightCommands(), ", "))
	}
	if err := parse(version, args); err != nil {
		return fmt.Errorf("--assert %q: %w", spec, err)
	}
	return nil
}

